# Part A · Section 3 — where murmurs are heard, maneuvers, innocent murmurs, rheumatic heart disease
TBL = '<table style="border-collapse:collapse;margin:10px 0;font-size:14px"><tr>{}</tr></table>'
def hdr(*cols):
    return TBL.format(''.join(f'<th style="border:1px solid #bbb;padding:4px 10px;text-align:left">{c}</th>' for c in cols))
SITES = ["Site 1","Site 2","Site 3","Site 4","Site 5","Site 6","Site 7"]

Q = [
dict(sec=3, img='auscSites', cap='Auscultation sites on the chest, numbered 1–7',
stem="A 63-year-old man comes to the office because of a 1-year history of fatigue and shortness of breath on exertion. Fifteen years ago he had an inferior myocardial infarction. His pulse is 80/min, and blood pressure is 118/74 mm Hg. The apical impulse is displaced laterally. A grade 3/6 holosystolic, blowing murmur is heard; it does not change with inspiration and is louder with sustained handgrip.{FIG}This murmur is most likely heard best at which of the following numbered sites?",
choices=SITES, key=5,
exp="A holosystolic, blowing murmur that is louder with handgrip and unchanged by breathing, in a patient with a displaced apex and a previous inferior infarct, is <b>mitral regurgitation</b> (here ischemic, from the posteromedial papillary muscle territory). It is heard best at the <b>apex — the mitral area, 5th intercostal space in the mid-clavicular line (site 6)</b> — and radiates to the axilla (site 7). Handgrip raises afterload and pushes more blood backward, so regurgitant murmurs get louder.<br>• Site 1: carotid area, where aortic stenosis radiates.<br>• Site 2: aortic area, right 2nd intercostal space.<br>• Site 3: pulmonic area, left 2nd intercostal space.<br>• Site 4: left sternal border, 3rd–4th spaces (aortic regurgitation, hypertrophic cardiomyopathy).<br>• Site 5: tricuspid area, left lower sternal border.<br><br><b>Educational objective:</b> Mitral regurgitation is heard best at the apex (5th intercostal space, mid-clavicular line) and radiates to the axilla.",
wrong={0:"Site 1 is over the carotid artery, where the murmur of aortic stenosis radiates.",
1:"Site 2 is the aortic area (right 2nd intercostal space), where aortic stenosis is loudest.",
2:"Site 3 is the pulmonic area (left 2nd intercostal space): pulmonic stenosis and the flow murmur of an atrial septal defect.",
3:"Site 4, the left sternal border, is where valvular aortic regurgitation and hypertrophic cardiomyopathy are heard best.",
4:"Site 5 is the tricuspid area; tricuspid regurgitation is also holosystolic but gets louder with inspiration, and this murmur does not.",
6:"Site 7, the axilla, is where mitral regurgitation radiates; it is loudest at the apex."},
eli5="A leaky mitral valve is heard best at the tip of the heart, below the nipple, and the sound travels toward the armpit."),

dict(sec=3, img='auscSites', cap='Auscultation sites on the chest, numbered 1–7',
stem="A 19-year-old college basketball player is evaluated after he fainted during a game. His father died suddenly at age 38. His pulse is 64/min, and blood pressure is 118/70 mm Hg. A harsh crescendo–decrescendo systolic murmur is heard; it does not radiate to the neck, it becomes louder when he stands up from a squat, and it softens with sustained handgrip. Carotid upstrokes are brisk.{FIG}This murmur is most likely heard best at which of the following numbered sites?",
choices=SITES[:6], key=3,
exp="Syncope on exertion, a family history of sudden death, and a systolic murmur that <b>gets louder on standing</b> (less preload) and softer with handgrip (a fuller ventricle) is <b>hypertrophic cardiomyopathy</b>. The obstruction is below the aortic valve, where the hypertrophied septum and the anterior mitral leaflet meet, so the murmur is loudest at the <b>left sternal border (site 4)</b> and <b>does not radiate to the carotids</b>; the carotid upstroke is brisk (sometimes bisferious), not delayed. Aortic stenosis, by contrast, is loudest at site 2 and radiates to site 1.<br><br><b>Educational objective:</b> The murmur of hypertrophic cardiomyopathy is loudest at the left sternal border, does not radiate to the carotids, and increases with maneuvers that reduce preload.",
wrong={0:"Site 1, over the carotid, is where aortic stenosis radiates; this murmur does not radiate to the neck.",
1:"Site 2, the aortic area, is where valvular aortic stenosis is loudest; that murmur softens on standing and radiates to the carotids.",
2:"Site 3, the pulmonic area, is where pulmonic stenosis and atrial septal defect flow murmurs are loudest.",
4:"Site 5 is the tricuspid area, for tricuspid regurgitation and ventricular septal defects.",
5:"Site 6, the apex, is where mitral regurgitation is loudest; that murmur gets louder with handgrip."},
eli5="In this condition the thick wall of the heart blocks blood just below the aortic valve, in the middle of the chest along the left edge of the breastbone. The noise stays there and doesn't travel up to the neck."),

dict(sec=3, img=None,
stem="A 22-year-old woman is evaluated for palpitations. Her older brother has hypertrophic cardiomyopathy. Echocardiography is scheduled. Her examination shows a grade 2/6 crescendo–decrescendo systolic murmur at the left sternal border." + hdr('Standing from a squat','Sustained handgrip') + "{FIG}If she has hypertrophic cardiomyopathy with outflow obstruction, which of the following sets of changes in the murmur is expected?",
choices=["Louder, louder","Louder, softer","No change, louder","Softer, louder","Softer, softer"], key=1,
exp="In hypertrophic cardiomyopathy the outflow obstruction is <b>dynamic</b>: the smaller the ventricle, the closer the septum and the anterior mitral leaflet come, and the worse the obstruction.<br>• <b>Standing</b> pools blood in the legs → less venous return → smaller ventricle → more obstruction → <b>louder</b>.<br>• <b>Sustained handgrip</b> raises afterload → the ventricle empties less and stays fuller → less obstruction → <b>softer</b>.<br>Aortic stenosis is <b>softer with both</b> (less flow on standing; a smaller gradient with handgrip). So standing or Valsalva, not handgrip, separates hypertrophic cardiomyopathy from aortic stenosis.<br><br><b>Educational objective:</b> The hypertrophic cardiomyopathy murmur gets louder with maneuvers that shrink the ventricle (standing, Valsalva strain) and softer with maneuvers that fill it or raise afterload (squatting, leg raise, handgrip).",
wrong={0:"Handgrip fills the ventricle and relieves the dynamic obstruction, so the murmur softens rather than getting louder.",
2:"Standing reduces preload and makes this murmur louder; handgrip softens it.",
3:"Softer on standing and louder with handgrip is the pattern of most other murmurs, such as mitral regurgitation, the reverse of hypertrophic cardiomyopathy.",
4:"Softer with both maneuvers is the pattern of aortic stenosis."},
eli5="In this heart, a smaller ventricle means a tighter blockage. Standing up empties the ventricle a bit so the murmur gets louder; squeezing a handgrip keeps the ventricle fuller so it gets softer."),

dict(sec=3, img='phonoMVP', cap='Phonocardiogram with a simultaneous electrocardiogram, recorded at the apex while supine',
stem="A 30-year-old woman comes to the office because of occasional palpitations. Her pulse is 70/min, and blood pressure is 106/68 mm Hg. A phonocardiogram recorded at the apex while she lies supine is shown.{FIG}Which of the following maneuvers is most likely to make the first systolic sound occur later in systole and shorten the murmur that follows it?",
choices=["Inhalation of amyl nitrite","Squatting from a standing position","Standing from a squatting position","Strain phase of the Valsalva maneuver"], key=1,
exp="A mid-systolic click followed by a late systolic murmur is <b>mitral valve prolapse</b>. The timing of the click depends on <b>ventricular volume</b>: a floppy leaflet prolapses once the ventricle has emptied enough that the leaflet is no longer held down. A <b>fuller ventricle</b> delays that point, so the click moves later and the murmur shortens. <b>Squatting</b> raises venous return (preload) and afterload, filling the ventricle. Standing, the Valsalva strain phase and amyl nitrite (a vasodilator that lowers afterload and preload) all shrink the ventricle and move the click earlier.<br><br><b>Educational objective:</b> In mitral valve prolapse, anything that fills the ventricle (squatting, leg raise, handgrip) delays the click and shortens the murmur; anything that shrinks it (standing, Valsalva) makes the click earlier.",
wrong={0:"Amyl nitrite dilates vessels, lowering afterload and venous return; the ventricle gets smaller and the click moves earlier.",
2:"Standing pools blood in the legs, shrinking the ventricle; the click comes earlier and the murmur lengthens.",
3:"The strain phase of Valsalva reduces venous return, so the click comes earlier."},
eli5="A floppy mitral flap pops back once the ventricle gets small enough. Squatting fills the ventricle with more blood, so it takes longer to get small and the pop happens later."),

dict(sec=3, img='phonoHolo', cap='Phonocardiogram with a simultaneous electrocardiogram, recorded at the left lower sternal border',
stem="A 34-year-old man who injects heroin comes to the emergency department because of a 2-week history of fever and fatigue. His temperature is 38.9°C (102°F), pulse is 108/min, and blood pressure is 118/70 mm Hg. A phonocardiogram recorded at the left lower sternal border is shown; the murmur becomes louder during inspiration. The liver edge is pulsatile.{FIG}Inspection of the neck is most likely to show which of the following findings?",
choices=["Absent a waves","Cannon a waves","Prominent v waves","Rise in jugular pressure on inspiration","Slow, attenuated y descent"], key=2,
exp="A holosystolic murmur at the left lower sternal border that is <b>louder with inspiration</b> (Carvallo sign) is <b>tricuspid regurgitation</b>; in someone who injects drugs, the cause is right-sided endocarditis. During ventricular systole blood leaks back into the right atrium, which is already filling from the venae cavae, so the atrial and jugular <b>v wave becomes tall</b> (often merging with the c wave into a large systolic wave), and the liver pulsates. Inspiration increases venous return to the right heart, so right-sided murmurs get louder.<br><br><b>Educational objective:</b> Tricuspid regurgitation produces a holosystolic murmur at the left lower sternal border that increases with inspiration, large jugular v waves and a pulsatile liver.",
wrong={0:"Absent a waves mean no organized atrial contraction (atrial fibrillation).",
1:"Cannon a waves occur when the atrium contracts against a closed tricuspid valve, as in complete heart block.",
3:"A rise in jugular pressure on inspiration (Kussmaul sign) suggests constrictive pericarditis or severe right ventricular failure; normally jugular pressure falls on inspiration.",
4:"A slow y descent suggests tricuspid stenosis or tamponade; in regurgitation the y descent is typically rapid."},
eli5="When the tricuspid valve leaks, each heartbeat shoots blood backward into the neck veins, so you see a big pulse wave in the neck. Breathing in brings more blood to the right heart, so the murmur gets louder."),

dict(sec=3, img=None,
stem="During a cardiovascular examination, a 25-year-old man is asked to bear down against a closed glottis and hold the strain for 15 seconds." + hdr('Venous return to the heart','Left ventricular stroke volume','Heart rate') + "{FIG}Which of the following sets of changes is expected during the sustained strain phase, compared with before the maneuver?",
choices=["Decreased, decreased, decreased","Decreased, decreased, increased","Decreased, increased, increased","Increased, decreased, increased","Increased, increased, decreased"], key=1,
exp="Bearing down raises intrathoracic pressure, which <b>compresses the great veins and cuts venous return</b>. Less filling → smaller stroke volume and cardiac output → falling blood pressure → baroreceptors fire less → <b>reflex tachycardia</b> and vasoconstriction. Because the ventricle is smaller, the strain phase is used to bring out the murmurs of hypertrophic cardiomyopathy and mitral valve prolapse (louder) while most others soften. On release, venous return surges, pressure overshoots, and a burst of vagal tone slows the heart — the same burst that can terminate a supraventricular tachycardia.<br><br><b>Educational objective:</b> The Valsalva strain phase decreases venous return and stroke volume, and the baroreflex raises heart rate; release causes an overshoot in pressure and a reflex bradycardia.",
wrong={0:"The heart rate rises, not falls, during the strain, because the baroreceptors sense the fall in pressure. Slowing happens after release.",
2:"With less venous return there is less filling, so stroke volume falls; it cannot rise.",
3:"Raised intrathoracic pressure impedes, not increases, venous return during the strain.",
4:"Increased return, increased stroke volume and a slower rate describe the release phase overshoot, not the strain."},
eli5="Straining squeezes the big veins in the chest, so less blood gets back to the heart and it pumps less. The body notices the pressure drop and speeds up the heart to make up for it."),

dict(sec=3, img='phonoMS', cap='Phonocardiogram with a simultaneous electrocardiogram in this patient',
stem="A 44-year-old woman who emigrated from Pakistan comes to the office because of a 1-year history of shortness of breath on exertion. Her pulse is 80/min and regular. A phonocardiogram recorded at the point of maximal impulse is shown.{FIG}Which of the following examination techniques will best bring out the diastolic murmur in this patient?",
choices=["Bell lightly at the apex with the patient lying on her left side","Bell at the left lower sternal border during deep inspiration","Diaphragm at the left sternal border, sitting forward in expiration","Diaphragm at the right second intercostal space while standing"], key=0,
exp="The phonocardiogram shows a sharp sound just after S2 followed by a decrescendo diastolic murmur that swells again before S1 (presystolic accentuation from atrial contraction in sinus rhythm): an <b>opening snap and diastolic rumble of mitral stenosis</b>. The rumble is <b>low-pitched</b>, so it is heard with the <b>bell</b>, applied lightly at the <b>apex</b>, with the patient turned onto her <b>left side</b>, which brings the apex against the chest wall.<br><br><b>Educational objective:</b> The low-pitched rumble of mitral stenosis is heard best with the bell at the apex in the left lateral decubitus position.",
wrong={1:"The bell at the left lower sternal border during inspiration is the technique for tricuspid stenosis, a right-sided lesion that gets louder with inspiration.",
2:"Sitting forward in expiration with the diaphragm at the left sternal border brings out the high-pitched murmur of aortic regurgitation.",
3:"The diaphragm at the right second intercostal space is for aortic stenosis, and standing would make most murmurs softer."},
eli5="A narrow mitral valve makes a low rumble, which the bell of the stethoscope picks up best. Rolling onto the left side brings the tip of the heart right up against the chest wall."),

dict(sec=3, img=None,
stem="A 6-year-old boy is brought for a well-child examination. He is active and has no symptoms. His growth is at the 50th percentile. His pulse is 92/min, and blood pressure is 98/60 mm Hg. A grade 2/6 low-pitched, vibratory, musical midsystolic murmur is heard at the left lower sternal border; it is louder when he lies supine and softer when he stands. The second heart sound splits normally with breathing. There are no clicks, no diastolic murmur, and femoral pulses are normal.{FIG}Which of the following is the most appropriate next step in management?",
choices=["Antistreptolysin O titer","Electrocardiography","Reassurance and routine follow-up","Referral to a pediatric cardiologist","Transthoracic echocardiography"], key=2,
exp="A soft (below grade 3), low-pitched, vibratory midsystolic murmur at the left lower sternal border that is louder supine, with normal S2 splitting and no other abnormality in a well child, is a <b>Still murmur</b> — the most common innocent murmur of childhood. Innocent murmurs are soft, systolic (or a continuous venous hum), change with position and have no associated findings. <b>Reassurance</b> is all that is needed. A diastolic murmur, a grade 3 or louder murmur, a thrill, a fixed split, a click, symptoms or abnormal pulses would prompt echocardiography.<br><br><b>Educational objective:</b> A Still murmur — soft, vibratory, midsystolic, at the left lower sternal border and louder supine — is innocent and needs only reassurance.",
wrong={0:"An antistreptolysin titer supports acute rheumatic fever; he has no fever, arthritis or carditis.",
1:"An electrocardiogram adds nothing when the murmur has every feature of an innocent murmur.",
3:"Referral is for murmurs with pathologic features; this one has none.",
4:"Echocardiography is indicated for pathologic features such as a diastolic murmur, a loud murmur, a thrill or a fixed split S2."},
eli5="Lots of healthy kids have a soft, buzzing heart murmur from blood moving fast through a normal heart. When everything else is normal, you just reassure the family."),

dict(sec=3, img=None,
stem="A 5-year-old girl is brought for a routine examination. She has no symptoms. While she sits upright, a soft continuous humming murmur is heard just above the right clavicle. It disappears when she lies flat, when she turns her head toward the right, and when light pressure is applied over the right internal jugular vein. Femoral pulses are normal.{FIG}Which of the following is the most likely cause of this sound?",
choices=["Arteriovenous fistula","Coarctation of the aorta","Patent ductus arteriosus","Pulmonary artery stenosis","Venous hum"], key=4,
exp="A soft continuous murmur heard <b>above the clavicle</b> that disappears when the child <b>lies flat, turns the head, or the jugular vein is compressed</b> is a <b>venous hum</b>, an innocent sound from turbulent flow where the jugular veins join the subclavian vein. Because it is venous, compressing the vein or lying supine abolishes it.<br><br><b>Educational objective:</b> A venous hum is an innocent continuous murmur above the clavicle that disappears with jugular compression, head turning or lying supine.",
wrong={0:"An arteriovenous fistula makes a continuous bruit that does not vanish with jugular compression or position.",
1:"Coarctation gives a systolic murmur (often heard over the back) with weak, delayed femoral pulses; hers are normal.",
2:"A patent ductus arteriosus gives a continuous machinery murmur below the left clavicle that does not disappear with position or jugular compression.",
3:"Peripheral pulmonary artery stenosis gives a systolic murmur heard over the back and axillae, unaffected by jugular compression."},
eli5="Blood rushing down the big neck vein can hum. Press on the vein or have the child lie down, and the hum stops, which tells you it's harmless."),

dict(sec=3, img=None,
stem="A 34-year-old man comes for a pre-employment physical examination. He has no symptoms and exercises regularly. His pulse is 64/min, and blood pressure is 128/62 mm Hg. A soft, grade 1/6, high-pitched decrescendo murmur is heard at the left sternal border immediately after the second heart sound when he sits forward and exhales. There is no thrill.{FIG}Which of the following is the most appropriate next step in management?",
choices=["Reassurance that the murmur is innocent","Repeat auscultation in 1 year","Serum brain natriuretic peptide measurement","Transthoracic echocardiography"], key=3,
exp="A high-pitched early diastolic decrescendo murmur at the left sternal border, best heard sitting forward in expiration, is <b>aortic regurgitation</b>, here mild. Its softness and his lack of symptoms do not make it innocent: <b>a diastolic murmur is almost always pathologic</b>. Innocent murmurs are systolic (or a continuous venous hum). He needs <b>echocardiography</b> to find the cause (bicuspid valve, root dilation) and to gauge severity and ventricular size.<br><br><b>Educational objective:</b> Any diastolic murmur, however soft and whatever the symptoms, warrants echocardiography, because innocent murmurs are systolic.",
wrong={0:"Innocent murmurs are soft systolic murmurs or a venous hum; a diastolic murmur is pathologic until proven otherwise.",
1:"Waiting a year without imaging could miss a dilated aortic root or a bicuspid valve.",
2:"Natriuretic peptides help in suspected heart failure; they do not identify or grade a valve lesion in an asymptomatic man."},
eli5="Harmless murmurs happen while the heart squeezes. A murmur while the heart is relaxing almost always means a real valve problem, so it needs an ultrasound."),

dict(sec=3, img=None,
stem="A 9-year-old girl is brought to the emergency department because of a 5-day history of fever and painful, swollen joints; the pain moved from her knees to her ankles and then to her right wrist. Three weeks ago she had a sore throat that was not treated. Her temperature is 38.6°C (101.5°F), pulse is 128/min, and blood pressure is 102/64 mm Hg. A soft holosystolic murmur is heard at the apex. Antistreptolysin O titer is elevated. Throat culture is negative.{FIG}Which of the following best explains the cardiac findings in this patient?",
choices=["Anti-M protein antibodies cross-reacting with cardiac tissue","Deposition of streptococcal antigen–antibody complexes in the valve","Direct invasion of the endocardium by group A streptococci","Exotoxin acting as a superantigen on T cells in the myocardium","Septic emboli from a streptococcal vegetation on the mitral valve"], key=0,
exp="Migratory polyarthritis, fever and new carditis about 3 weeks after untreated streptococcal pharyngitis, with a raised antistreptolysin O titer, is <b>acute rheumatic fever</b>. It is <b>molecular mimicry</b>: antibodies and T cells against the streptococcal <b>M protein</b> cross-react with cardiac myosin and valve tissue (in about 3% of untreated infections). The throat culture is often negative by the time carditis appears, because the infection has cleared. The carditis is a pancarditis, and the valvulitis (mitral first) heals by fibrosis, giving mitral stenosis decades later. Major criteria (J♥NES): joints, carditis, nodules, erythema marginatum, Sydenham chorea.<br><br><b>Educational objective:</b> Acute rheumatic fever is caused by molecular mimicry: antibodies against the group A streptococcal M protein cross-react with cardiac tissue.",
wrong={1:"Immune-complex deposition is the mechanism of poststreptococcal glomerulonephritis, not rheumatic carditis.",
2:"Rheumatic carditis is sterile; there are no organisms in the heart, which is why the culture is negative and the latency is weeks.",
3:"Superantigen exotoxins cause streptococcal toxic shock syndrome, with shock and rash, not migratory arthritis and carditis weeks later.",
4:"Septic emboli come from infective endocarditis; rheumatic vegetations are small, sterile and do not embolize."},
eli5="The strep germ wears a coat protein that looks a lot like heart tissue. The immune system makes antibodies against the germ, and some of them attack the heart by mistake."),

dict(sec=3, img='aschoff', cap='Photomicrograph of a myocardial biopsy specimen (hematoxylin and eosin stain)',
stem="A 10-year-old boy has fever, migratory polyarthritis and a new apical murmur 4 weeks after a sore throat. An endomyocardial biopsy specimen is shown.{FIG}If his condition is untreated and recurs, which of the following valve lesions is he most likely to develop decades later?",
choices=["Aortic stenosis from a bicuspid valve","Mitral stenosis with fused commissures","Mitral valve prolapse with myxoid leaflets","Pulmonic stenosis with a domed valve","Tricuspid regurgitation from vegetations"], key=1,
exp="The lesion is an <b>Aschoff body</b> — a focus of T cells, plasma cells and activated macrophages; the macrophages with wavy, \"caterpillar\" chromatin are <b>Anitschkow cells</b>. It is the hallmark of <b>acute rheumatic carditis</b>. The valvulitis heals by <b>fibrosis</b>; with recurrent attacks, the mitral leaflets thicken and their <b>commissures fuse</b>, producing <b>mitral stenosis</b> (the \"fish-mouth\" valve) decades later. Rheumatic disease is the most common cause of mitral stenosis worldwide.<br><br><b>Educational objective:</b> Aschoff bodies with Anitschkow cells mark acute rheumatic carditis, which scars the mitral valve into stenosis with fused commissures decades later.",
wrong={0:"A bicuspid aortic valve is congenital, not a consequence of rheumatic fever.",
2:"Prolapse comes from myxomatous degeneration (proteoglycan expansion), not post-inflammatory scarring.",
3:"Pulmonic stenosis with a domed valve is congenital (associated with Noonan syndrome); rheumatic disease rarely affects the pulmonic valve.",
4:"Vegetations with tricuspid regurgitation are infective endocarditis, typically in people who inject drugs."},
eli5="This little nest of immune cells is the fingerprint of rheumatic fever. As it heals, the mitral valve scars and its flaps stick together, so years later the valve becomes narrow."),

dict(sec=3, img='msGross', cap='Mitral valve viewed from the left atrium at autopsy',
stem="A 64-year-old woman who emigrated from Guatemala dies of a stroke. For 10 years she had atrial fibrillation and shortness of breath on exertion. The mitral valve at autopsy is shown.{FIG}Which of the following infections most likely began the process that produced this valve?",
choices=["Coxsackie B virus myocarditis","Group A streptococcal pharyngitis","Streptococcus gallolyticus bacteremia","Syphilitic aortitis","Viridans streptococcal endocarditis"], key=1,
exp="The valve is thickened and calcified, with <b>fused commissures leaving a small slit-like (\"fish-mouth\") orifice</b>: <b>rheumatic mitral stenosis</b>. The process began decades earlier with <b>group A streptococcal pharyngitis</b> followed by acute rheumatic fever; molecular mimicry inflamed the valve, which healed by fibrosis and later calcified. The enlarged left atrium caused atrial fibrillation, and stasis in the atrium produced the thrombus that caused her stroke.<br><br><b>Educational objective:</b> A fish-mouth mitral valve with fused commissures is chronic rheumatic heart disease, the late result of group A streptococcal pharyngitis.",
wrong={0:"Coxsackie B causes viral myocarditis and pericarditis, not commissural fusion of the mitral valve.",
2:"Streptococcus gallolyticus causes endocarditis associated with colon cancer; it destroys leaflets rather than fusing commissures.",
3:"Syphilitic aortitis dilates the aortic root, producing aortic regurgitation, not mitral stenosis.",
4:"Viridans streptococcal endocarditis usually seeds a valve already damaged by rheumatic disease; it is not the cause of the scarring."},
eli5="Years earlier, a strep throat set off rheumatic fever, which scarred the mitral valve. The flaps glued together until only a small slit was left."),
]
